def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def is_cell(tok: str | None) -> bool:
        return (
            tok is not None
            and len(tok) >= 2
            and "A" <= tok[0] <= "Z"
            and tok[1:].isdigit()
        )

    def tokenize(src: str) -> list[str]:
        toks: list[str] = []
        i, n = 0, len(src)
        while i < n:
            c = src[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit():
                j = i + 1
                while j < n and src[j].isdigit():
                    j += 1
                toks.append(src[i:j])
                i = j
                continue
            if "A" <= c <= "Z":
                j = i + 1
                while j < n and "A" <= src[j] <= "Z":
                    j += 1
                if j == i + 1 and j < n and src[j].isdigit():
                    k = j + 1
                    while k < n and src[k].isdigit():
                        k += 1
                    toks.append(src[i:k])
                    i = k
                else:
                    toks.append(src[i:j])
                    i = j
                continue
            if src.startswith("<>", i) or src.startswith("<=", i) or src.startswith(">=", i):
                toks.append(src[i : i + 2])
                i += 2
                continue
            toks.append(c)
            i += 1
        return toks

    class Parser:
        def __init__(self, toks: list[str]) -> None:
            self.toks = toks
            self.i = 0

        def peek(self, k: int = 0) -> str | None:
            j = self.i + k
            return self.toks[j] if j < len(self.toks) else None

        def pop(self) -> str:
            t = self.toks[self.i]
            self.i += 1
            return t

    def parse_expr(p: Parser):
        node = parse_term(p)
        while p.peek() in ("+", "-"):
            op = p.pop()
            node = ("bin", op, node, parse_term(p))
        return node

    def parse_term(p: Parser):
        node = parse_factor(p)
        while p.peek() in ("*", "/"):
            op = p.pop()
            node = ("bin", op, node, parse_factor(p))
        return node

    def parse_factor(p: Parser):
        if p.peek() == "-":
            p.pop()
            return ("unary", parse_factor(p))
        return parse_atom(p)

    def parse_atom(p: Parser):
        t = p.pop()
        if t.isdigit():
            return ("num", int(t))
        if t == "(":
            node = parse_expr(p)
            p.pop()
            return node
        if t in ("SUM", "MIN", "MAX"):
            p.pop()
            args = []
            while True:
                if is_cell(p.peek()) and p.peek(1) == ":":
                    a = p.pop()
                    p.pop()
                    b = p.pop()
                    args.append(("range", a, b))
                else:
                    args.append(("expr", parse_expr(p)))
                if p.peek() == ",":
                    p.pop()
                    continue
                break
            p.pop()
            return ("agg", t, args)
        if t == "IF":
            p.pop()
            left = parse_expr(p)
            op = p.pop()
            right = parse_expr(p)
            p.pop()
            then_b = parse_expr(p)
            p.pop()
            else_b = parse_expr(p)
            p.pop()
            return ("if", left, op, right, then_b, else_b)
        return ("ref", t)

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def cmp_op(op: str, a: int, b: int) -> bool:
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def range_names(a: str, b: str):
        c1, r1 = ord(a[0]), int(a[1:])
        c2, r2 = ord(b[0]), int(b[1:])
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                yield chr(c) + str(r)

    def eval_node(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return eval_cell(node[1])
        if kind == "unary":
            v = eval_node(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            _, op, left, right = node
            lv = eval_node(left)
            if isinstance(lv, str):
                return lv
            rv = eval_node(right)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            if rv == 0:
                return "#DIV/0!"
            return trunc_div(lv, rv)
        if kind == "agg":
            _, fn, args = node
            vals: list[int] = []
            for arg in args:
                if arg[0] == "range":
                    for name in range_names(arg[1], arg[2]):
                        if name not in cells:
                            continue
                        v = eval_cell(name)
                        if isinstance(v, str):
                            return v
                        vals.append(v)
                else:
                    v = eval_node(arg[1])
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            if not vals:
                return 0
            if fn == "SUM":
                return sum(vals)
            if fn == "MIN":
                return min(vals)
            return max(vals)
        _, left, op, right, then_b, else_b = node
        lv = eval_node(left)
        if isinstance(lv, str):
            return lv
        rv = eval_node(right)
        if isinstance(rv, str):
            return rv
        return eval_node(then_b if cmp_op(op, lv, rv) else else_b)

    def eval_cell(name: str):
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            val = eval_node(parse_expr(Parser(tokenize(raw[1:]))))
        else:
            val = int(raw)
        visiting.remove(name)
        memo[name] = val
        return val

    return {name: eval_cell(name) for name in cells}
